141	        int delta = ParamUtil.getInteger(renderRequest, "delta", DEFAULT_DELTA);
142	        String orderByCol = ParamUtil.getString(renderRequest, "orderByCol", DEFAULT_COL);
143	        String orderByType = ParamUtil.getString(renderRequest, "orderByType", DEFAULT_TYPE);
144	        String queryDettaglio = ParamUtil.getString(renderRequest, "mvcRenderCommandName");
145	
146	        int[] limits = SearchPaginationUtil.calculateStartAndEnd(cur, delta);
147	
148	
149	        ServiceContext serviceContext = ServiceContextFactory.getInstance(renderRequest);
150	
151	        boolean aperto = DEFAULT_TAB.equals(queryTab) || DEFAULT_TAB_EVENTI.equals(queryTab);
152	
153	        int start = limits[0];
154	        int end = limits[1];
155	        boolean asc = !DEFAULT_TYPE.equals(orderByType);
156	
157	        long userId = themeDisplay.getUserId();
158	        long groupId = themeDisplay.getScopeGroupId();
159	
160	        List<Long> idSottoOrganizzazioni = scrivaniaOperatoreFrontendService.getUserSubOrganization(groupId, userId);
161	
162	        if(queryDettaglio.isEmpty()) {
163	            List<BandoDTO> bandi = bandoLocalService.findBandi(serviceContext, aperto, start, end, orderByCol, asc, idSottoOrganizzazioni, visualizzazioneEventi)
164	                    .stream()
165	                    .map(b -> scrivaniaOperatoreFrontendService.mapBando(b))
