179	    private void handleRichiesteReferente(RenderRequest renderRequest, ThemeDisplay themeDisplay, boolean visualizzazioneEventi) throws PortalException {
180	        int cur = ParamUtil.getInteger(renderRequest, SearchContainer
181	                .DEFAULT_CUR_PARAM, DEFAULT_CUR);
182	        int delta = ParamUtil.getInteger(renderRequest, SearchContainer.DEFAULT_DELTA_PARAM, DEFAULT_DELTA);
183	        String tab = ParamUtil.getString(renderRequest, ReferenteKeys.PARAM_TAB, "in.arrivo");
184	        String bando = ParamUtil.getString(renderRequest, ReferenteKeys.PARAM_BANDO);
185	        String codiceFiscale = ParamUtil.getString(renderRequest, ReferenteKeys.PARAM_CODICE_FISCALE);
186	
187	        User user = themeDisplay.getUser();
188	        DominioIstanza dominioGestioneReferente = visualizzazioneEventi ? DominioIstanza.EVENTI : DominioIstanza.BANDI;
189	        Dominio dominio = Dominio.valueOf(dominioGestioneReferente.name());
190	
191	        int[] limits = SearchPaginationUtil.calculateStartAndEnd(cur, delta);
192	        OperatoreSearchFiltersDTO filters = new OperatoreSearchFiltersDTO();
193	        filters.setGroupId(themeDisplay.getScopeGroupId());
194	        filters.setStart(limits[0]);
195	        filters.setEnd(limits[1]);
196	        filters.setDominio(dominioGestioneReferente);
197	        filters.setOperatoreUserId(user.getUserId());
198	        filters.setServizioId(bando);
199	        filters.setCodiceFiscaleLike(codiceFiscale);
200	        filters.setTabCorrente(TabCorrenteEnum.findByValue(tab));
201	        List<BandoDTO> bandi = new ArrayList<>();
202	
203	        long[] userOrganizationIds = user.getOrganizationIds();
204	        if (Validator.isNotNull(userOrganizationIds)) {
205	            List<Long> organizationIds = Arrays.stream(userOrganizationIds)
206	                    .boxed()
207	                    .collect(Collectors.toList());
208	            List<Bando> sottoOrganizzazioneList = bandoLocalService.getBandiBySubOrganizationAndDominio(
209	                    organizationIds,
210	                    themeDisplay.getScopeGroupId(),
211	                    themeDisplay.getCompanyId(), dominio.name()
212	            );
213	            if (ListUtil.isNotNull(sottoOrganizzazioneList) && ListUtil.isNotEmpty(sottoOrganizzazioneList)) {
214	                bandi = sottoOrganizzazioneList
215	                        .stream()
216	                        .map(b -> scrivaniaOperatoreFrontendService.mapBando(b))
217	                        .collect(Collectors.toList());
218	
219	                List<Long> servizioIds = sottoOrganizzazioneList.stream()
220	                        .map(BandoModel::getBandoId)
221	                        .collect(Collectors.toList());
222	                filters.setServizioIds(servizioIds);
223	            }
224	        }
225	
226	        SearchResultDTO search = gestioneReferenteMiddlewareService.searchRichiesteOperatore(filters);
227	
228	        renderRequest.setAttribute(ReferenteKeys.ATTR_TAB, tab);
229	        renderRequest.setAttribute(ReferenteKeys.ATTR_LISTA, search.getItems());
230	        renderRequest.setAttribute(ReferenteKeys.ATTR_TOTALE, search.getTotal());
231	        renderRequest.setAttribute(ReferenteKeys.ATTR_BANDI, bandi);
232	    }
233	
234	    @Activate
235	    @Modified
236	    protected void activate(Map<String, Object> properties) {
237	        scrivaniaBandiConfiguration = ConfigurableUtil.createConfigurable(ScrivaniaBandiConfiguration.class, properties);
238	    }
239	}

