@Component(
        immediate = true,
        property = {
                "com.liferay.portlet.display-category=category.bandi",
                "com.liferay.portlet.header-portlet-css=/css/main.css",
				"com.liferay.portlet.header-portlet-css=/libs/tempusdominus-bootstrap-4/css/tempusdominus-bootstrap-4.min.css",
                "com.liferay.portlet.header-portlet-css=/libs/alpaca-custom/alpaca.css",
                "com.liferay.portlet.header-portlet-css=/libs/jquery.handsontable/jquery.handsontable.full.css",
                "com.liferay.portlet.header-portlet-css=/libs_custom/simple-calendar/simple-calendar.css",
				"com.liferay.portlet.header-portlet-javascript=/libs/jquery-ui-dist/jquery-ui.min.js", //
				"com.liferay.portlet.header-portlet-javascript=/libs/jquery-blockui/jquery.blockUI.js",
                "com.liferay.portlet.header-portlet-javascript=/libs/jquery.handsontable/jquery.handsontable.full.js",
				"com.liferay.portlet.header-portlet-javascript=/libs/handlebars/handlebars.min.js", //
                "com.liferay.portlet.header-portlet-javascript=/libs/alpaca-custom/alpaca-bo.min.js",
                "com.liferay.portlet.header-portlet-javascript=/dist/custom-fields.min.js",
                "com.liferay.portlet.header-portlet-javascript=/libs/moment/moment-with-locales.min.js",
				"com.liferay.portlet.header-portlet-javascript=/libs/tempusdominus-bootstrap-4/js/tempusdominus-bootstrap-4.min.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs/jquery.deserialize/jquery.deserialize.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs/jquery.serializeObject/jquery.serializeObject.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs/jquery.repeater/jquery.repeater.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs/ace.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs/datepicker-it.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs_custom/simple-calendar/jquery.simple-calendar.min.js",
                "com.liferay.portlet.footer-portlet-javascript=/libs/jquery.priceformat.js",
                "com.liferay.portlet.instanceable=true",
                "javax.portlet.display-name=ScrivaniaOperatoreBandi",
                "javax.portlet.init-param.template-path=/",
                "javax.portlet.init-param.view-template=/view.jsp",
                "javax.portlet.name=" + ScrivaniaOperatoreBandiPortletKeys.SCRIVANIA_OPERATORE_BANDI,
                "javax.portlet.resource-bundle=content.Language",
                "javax.portlet.security-role-ref=power-user,user"
        },
        service = Portlet.class
)
public class ScrivaniaOperatoreBandiPortlet extends MVCPortlet {

    public static final Log _log = LogFactoryUtil.getLog(ScrivaniaOperatoreBandiPortlet.class);
    public static final String DEFAULT_TAB = "bandi.aperti";
    public static final String DEFAULT_TAB_EVENTI = "eventi.aperti";
    public static final String DEFAULT_TYPE = "desc";
    public static final int DEFAULT_CUR = 1;
    public static final int DEFAULT_DELTA = 10;
    public static final String DEFAULT_COL = "dataInizio";

    @Reference
    private BandoLocalService bandoLocalService;

    @Reference
    private ScrivaniaOperatoreBandiFrontendService scrivaniaOperatoreFrontendService;
    @Reference
    private AuditService auditService;
    @Reference
    private GestioneReferenteMiddlewareService gestioneReferenteMiddlewareService;
    @Reference
    private TipologiaBandoLocalService tipologiaBandoLocalService;

    private volatile ScrivaniaBandiConfiguration scrivaniaBandiConfiguration;

    @Override
    public void render(RenderRequest renderRequest, RenderResponse renderResponse) throws PortletException, IOException {
        String queryTab = ParamUtil.getString(renderRequest, ScrivaniaOperatoreBandiPortletKeys.QUERY_TAB, DEFAULT_TAB);
        ThemeDisplay themeDisplay = (ThemeDisplay) renderRequest.getAttribute(WebKeys.THEME_DISPLAY);
        boolean visualizzazioneEventi = scrivaniaOperatoreFrontendService.isScrivaniaEventi(renderRequest);

        try {
            if (ScrivaniaOperatoreBandiPortletKeys.TAB_RICHIESTE_REFERENTE.equals(queryTab)) {
                handleRichiesteReferente(renderRequest, themeDisplay, visualizzazioneEventi);
            } else {
                handleBandi(renderRequest, queryTab, themeDisplay, visualizzazioneEventi);
            }
        } catch (Exception e) {
        	auditService.saveErrorLog(renderRequest, e.getMessage());
            _log.error(e);
            SessionErrors.add(renderRequest, "errore-generico");
        }

        renderRequest.setAttribute("isGestoreCambioReferente", gestioneReferenteMiddlewareService.isGestoreCambioReferente(themeDisplay.getUserId()));
        renderRequest.setAttribute("isAdmin", scrivaniaOperatoreFrontendService.isAdmin(themeDisplay.getUserId()));
        renderRequest.setAttribute("tabs", scrivaniaOperatoreFrontendService.getTabsByUser(themeDisplay.getUserId(), visualizzazioneEventi));
        renderRequest.setAttribute("isScrivaniaEventi", visualizzazioneEventi);
        renderRequest.setAttribute("queryTab", queryTab);

        super.render(renderRequest, renderResponse);
    }

    private void handleBandi(RenderRequest renderRequest, String queryTab, ThemeDisplay themeDisplay, boolean visualizzazioneEventi) throws PortalException {
        int cur = ParamUtil.getInteger(renderRequest, "cur", DEFAULT_CUR);
        int delta = ParamUtil.getInteger(renderRequest, "delta", DEFAULT_DELTA);
        String orderByCol = ParamUtil.getString(renderRequest, "orderByCol", DEFAULT_COL);
        String orderByType = ParamUtil.getString(renderRequest, "orderByType", DEFAULT_TYPE);
        String queryDettaglio = ParamUtil.getString(renderRequest, "mvcRenderCommandName");

        int[] limits = SearchPaginationUtil.calculateStartAndEnd(cur, delta);


        ServiceContext serviceContext = ServiceContextFactory.getInstance(renderRequest);

        boolean aperto = DEFAULT_TAB.equals(queryTab) || DEFAULT_TAB_EVENTI.equals(queryTab);

        int start = limits[0];
        int end = limits[1];
        boolean asc = !DEFAULT_TYPE.equals(orderByType);

        long userId = themeDisplay.getUserId();
        long groupId = themeDisplay.getScopeGroupId();

        List<Long> idSottoOrganizzazioni = scrivaniaOperatoreFrontendService.getUserSubOrganization(groupId, userId);

        if(queryDettaglio.isEmpty()) {
            List<BandoDTO> bandi = bandoLocalService.findBandi(serviceContext, aperto, start, end, orderByCol, asc, idSottoOrganizzazioni, visualizzazioneEventi)
                    .stream()
                    .map(b -> scrivaniaOperatoreFrontendService.mapBando(b))
                    .collect(Collectors.toList());
            int countBandi = bandoLocalService.countBandi(serviceContext, aperto, idSottoOrganizzazioni, visualizzazioneEventi);


            renderRequest.setAttribute("listaBandi", bandi);
            renderRequest.setAttribute("countBandi", countBandi);
        }

        renderRequest.setAttribute("orderByCol", orderByCol);
        renderRequest.setAttribute("orderByType", orderByType);
        renderRequest.setAttribute(ScrivaniaBandiConfiguration.class.getName(), scrivaniaBandiConfiguration);
    }

    private void handleRichiesteReferente(RenderRequest renderRequest, ThemeDisplay themeDisplay, boolean visualizzazioneEventi) throws PortalException {
        int cur = ParamUtil.getInteger(renderRequest, SearchContainer
                .DEFAULT_CUR_PARAM, DEFAULT_CUR);
        int delta = ParamUtil.getInteger(renderRequest, SearchContainer.DEFAULT_DELTA_PARAM, DEFAULT_DELTA);
        String tab = ParamUtil.getString(renderRequest, ReferenteKeys.PARAM_TAB, "in.arrivo");
        String bando = ParamUtil.getString(renderRequest, ReferenteKeys.PARAM_BANDO);
        String codiceFiscale = ParamUtil.getString(renderRequest, ReferenteKeys.PARAM_CODICE_FISCALE);

        User user = themeDisplay.getUser();
        DominioIstanza dominioGestioneReferente = visualizzazioneEventi ? DominioIstanza.EVENTI : DominioIstanza.BANDI;
        Dominio dominio = Dominio.valueOf(dominioGestioneReferente.name());

        int[] limits = SearchPaginationUtil.calculateStartAndEnd(cur, delta);
        OperatoreSearchFiltersDTO filters = new OperatoreSearchFiltersDTO();
        filters.setGroupId(themeDisplay.getScopeGroupId());
        filters.setStart(limits[0]);
        filters.setEnd(limits[1]);
        filters.setDominio(dominioGestioneReferente);
        filters.setOperatoreUserId(user.getUserId());
        filters.setServizioId(bando);
        filters.setCodiceFiscaleLike(codiceFiscale);
        filters.setTabCorrente(TabCorrenteEnum.findByValue(tab));
        List<BandoDTO> bandi = new ArrayList<>();

        long[] userOrganizationIds = user.getOrganizationIds();
        if (Validator.isNotNull(userOrganizationIds)) {
            List<Long> organizationIds = Arrays.stream(userOrganizationIds)
                    .boxed()
                    .collect(Collectors.toList());
            List<Bando> sottoOrganizzazioneList = bandoLocalService.getBandiBySubOrganizationAndDominio(
                    organizationIds,
                    themeDisplay.getScopeGroupId(),
                    themeDisplay.getCompanyId(), dominio.name()
            );
            if (ListUtil.isNotNull(sottoOrganizzazioneList) && ListUtil.isNotEmpty(sottoOrganizzazioneList)) {
                bandi = sottoOrganizzazioneList
                        .stream()
                        .map(b -> scrivaniaOperatoreFrontendService.mapBando(b))
                        .collect(Collectors.toList());

                List<Long> servizioIds = sottoOrganizzazioneList.stream()
                        .map(BandoModel::getBandoId)
                        .collect(Collectors.toList());
                filters.setServizioIds(servizioIds);
            }
        }

        SearchResultDTO search = gestioneReferenteMiddlewareService.searchRichiesteOperatore(filters);

        renderRequest.setAttribute(ReferenteKeys.ATTR_TAB, tab);
        renderRequest.setAttribute(ReferenteKeys.ATTR_LISTA, search.getItems());
        renderRequest.setAttribute(ReferenteKeys.ATTR_TOTALE, search.getTotal());
        renderRequest.setAttribute(ReferenteKeys.ATTR_BANDI, bandi);
    }

    @Activate
    @Modified
    protected void activate(Map<String, Object> properties) {
        scrivaniaBandiConfiguration = ConfigurableUtil.createConfigurable(ScrivaniaBandiConfiguration.class, properties);
    }
}

