import it.servizidigitali.common.utility.enumeration.UserCustomAttributes;

/**
 * Implementazione di {@link OldUserResolver}.
 */
@Component(immediate = true, service = OldUserResolver.class)
public class OldUserResolverImpl implements OldUserResolver {

	private static final Log log = LogFactoryUtil.getLog(OldUserResolverImpl.class);

	@Reference
	private UserLocalService userLocalService;

	@Override
	public String getOldScreenName(long userId) {
		User user = userLocalService.fetchUser(userId);
		if (user == null) {
			return null;
		}

		ExpandoBridge expandoBridge = user.getExpandoBridge();
		String attributeName = UserCustomAttributes.OLD_SCREEN_NAME.getNomeAttributo();

		if (!expandoBridge.hasAttribute(attributeName)) {
			return null;
		}

		Serializable value = expandoBridge.getAttribute(attributeName, false);
		if (value == null) {
			return null;
		}

		String oldScreenName = value.toString();
		return Validator.isNotNull(oldScreenName) ? oldScreenName : null;
	}

	@Override
	public Long getOldUserId(long userId) {
		User user = userLocalService.fetchUser(userId);
		if (user == null) {
			return null;
		}

		String oldScreenName = getOldScreenName(userId);
		if (Validator.isNull(oldScreenName)) {
			return null;
		}

		User oldUser = userLocalService.fetchUserByScreenName(user.getCompanyId(), oldScreenName);
		if (oldUser == null) {
			log.debug("getOldUserId :: vecchia utenza non trovata per screenName " + oldScreenName);
			return null;
		}

		return oldUser.getUserId();
	}

	@Override
	public String getOldScreenNameByScreenName(long companyId, String screenName) {
		if (companyId <= 0 || Validator.isNull(screenName)) {
			return null;
		}

		User user = userLocalService.fetchUserByScreenName(companyId, screenName);
		if (user == null) {
			return null;
		}

		return getOldScreenName(user.getUserId());
	}
}

