public Map<String, Task> getUserTasks(ServiceContext serviceContext, List<VariableQueryParameter> variableQueryParameters, int firstResult, int maxResults, VariableSortOrder variableSortOrder) {
    try {
        long userId = serviceContext.getUserId();
        User currentUser = userLocalService.getUser(userId);

        List<String> tenantIds = new ArrayList<String>();
        tenantIds.add(String.valueOf(serviceContext.getScopeGroup().getOrganizationId()));

        List<Task> searchTasks = camundaClient.searchTasks(tenantIds, String.valueOf(currentUser.getUserId()), null,
                variableQueryParameters, firstResult, maxResults, variableSortOrder.getSortName(), variableSortOrder.getSortOrder(), variableSortOrder.getSortType());

        Map<String, Task> map = new LinkedHashMap<>();
        for (Task task : searchTasks) {
            map.put(task.getProcessInstanceId(), task);
        }

        addOldUserTasks(map, tenantIds, currentUser.getUserId(), variableQueryParameters, firstResult, maxResults, variableSortOrder.getSortName(), variableSortOrder.getSortOrder(),
                variableSortOrder.getSortType());

        return map;
    }
    catch (PortalException e) {
        log.error("getProcessInstanceIds :: " + e.getMessage(), e);
    }
    catch (CamundaClientException e) {
        log.error("getProcessInstanceIds :: " + e.getMessage(), e);
    }
    return null;
}

/**
 * Continuità operativa migrazione SPID: affianca ai task del nuovo userId quelli ancora assegnati al
 * vecchio userId quando l'operatore è migrato ({@code old_screen_name} valorizzato). No-op per gli
 * utenti non migrati. Le due interrogazioni Camunda usano assignee distinti (l'API espone un solo
 * {@code assignee}); l'eventuale paginazione è applicata a ciascun assignee separatamente.
 */
private void addOldUserTasks(Map<String, Task> map, List<String> tenantIds, long currentUserId, List<VariableQueryParameter> variableQueryParameters, int firstResult, int maxResults,
        String sortName, String sortOrder, String sortType) throws CamundaClientException {

    Long oldUserId = oldUserResolver.getOldUserId(currentUserId);
    if (oldUserId == null) {
        return;
    }

    List<Task> oldTasks = camundaClient.searchTasks(tenantIds, String.valueOf(oldUserId), null, variableQueryParameters, firstResult, maxResults, sortName, sortOrder, sortType);
    if (oldTasks != null) {
        for (Task task : oldTasks) {
            map.putIfAbsent(task.getProcessInstanceId(), task);
        }
    }
}

